'use client'

import type { ComponentProps } from 'react'
import { ToggleGroup } from '@base-ui/react/toggle-group'
import { cn } from '@/lib/utils'
import styles from './ButtonGroup.module.css'

export interface ButtonGroupProps
  extends Omit<ComponentProps<'div'>, 'defaultValue' | 'onChange' | 'dir'> {
  /** `separate`: ToggleButtons 4px apart. `joined`: one bar, inner corners square, borders shared. */
  type?: 'separate' | 'joined'
  /** Controlled: the `value` of the ToggleButton that is on. Pair with `onValueChange`. */
  value?: string
  /** Uncontrolled: the value on at first. */
  defaultValue?: string
  /** Called with the value of the ToggleButton just turned on. */
  onValueChange?: (value: string) => void
  /** Disables every toggle in the group. */
  disabled?: boolean
}

/** ToggleButtons that share one selection, exactly one on at a time, like Tabs. */
export function ButtonGroup({
  type = 'separate',
  value,
  defaultValue,
  onValueChange,
  className,
  ...props
}: ButtonGroupProps) {
  return (
    <ToggleGroup
      {...props}
      value={value === undefined ? undefined : [value]}
      defaultValue={defaultValue === undefined ? undefined : [defaultValue]}
      onValueChange={(next, details) => {
        // Once one is on, pressing it again does not leave none on.
        if (next.length === 0) return details.cancel()
        onValueChange?.(next[0])
      }}
      className={cn(styles[type], className)}
    />
  )
}

/* Separate: ToggleButtons in a row, 4px apart, each keeping its own corners
   and border; a toggle never shrinks below its content. */
.separate {
  display: inline-flex;
  /* One row: it does not wrap. */
  gap: var(--space-1);
}

.separate > * {
  flex: 1 0 auto;
}

/* Joined: one bar. The toggles keep their own size and colour; the group
   only joins them. Inner corners go square and each toggle after the first
   overlaps the previous one by its 1px border, so two outlined toggles share
   one line instead of drawing a double one. Two classes' worth of
   specificity, so it outranks Button's size class whichever stylesheet
   loads first. */
.joined {
  display: inline-flex;
  /* Keeps the z-index below inside the group. */
  isolation: isolate;
}

.joined > :not(:first-child) {
  /* stylelint-disable-next-line scale-unlimited/declaration-strict-value -- the toggles' 1px border, see above */
  margin-inline-start: -1px;
  border-start-start-radius: 0;
  border-end-start-radius: 0;
}

.joined > :not(:last-child) {
  border-start-end-radius: 0;
  border-end-end-radius: 0;
}

/* The toggle that is on has its own border colour; raised, it draws over
   the neighbour's line it overlaps. Focus goes higher still so the ring is
   never cut by the next toggle. */
.joined > [aria-pressed='true'] {
  /* stylelint-disable-next-line scale-unlimited/declaration-strict-value -- local stacking inside the group, not a global layer */
  z-index: 1;
}

.joined > :focus-visible {
  /* stylelint-disable-next-line scale-unlimited/declaration-strict-value -- local stacking inside the group, not a global layer */
  z-index: 2;
}
